insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-01','C1','認知類','比肩','固執己見讀法','堅持自己一套方法，聽不進更有效的做法','別只靠重讀。實證最有效的是「主動回憶」：讀完闔書默寫重點，再用一種公認有效的方法做一題比對正確率，讓效果決定方法。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-02','C1','認知類','比肩','同儕進度比較','老盯著別人讀到哪，思緒一直被拉走','社會比較會搶走專注。關掉進度群組，把基準改成「跟昨天的自己比」，只記錄自己今天完成的題數與弄懂的觀念。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-03','C1','認知類','比肩','不肯求助硬鑽','一題卡很久也不問，硬要自己想通','用 if-then 執行意圖：「若一題卡超過15分鐘，就標記、跳過、稍後集中問」，把無限鑽牛角尖換成具體提問。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-04','C1','認知類','劫財','多工分心','同時開好幾科，結果哪科都沒進去','多工會讓每件都變淺。改單工＋番茄鐘：一次只開一科、其餘分頁全關，專注25分鐘再休5分，完成一段才換科。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-05','C1','認知類','劫財','急著翻頁','沒讀懂就想往下衝，吸收很淺','讀懂比讀快重要。每讀一小段就用主動回憶闔書講一次重點，講不出來再回看，把速度換成真正吸收。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-06','C1','認知類','劫財','雜訊搶神','一有通知就被勾走思緒','通知是最強的分心源。手機調勿擾＋灰階、放到看不到的地方，專注25分鐘再一次處理訊息（刺激控制）。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-07','C1','認知類','食神','越讀越離題','查一個點延伸到一堆無關內容','延伸查詢會吃掉主線。把岔出去的點寫到「之後再查」清單，先用番茄鐘做完當前段落，離題就把視線拉回那一行。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-08','C1','認知類','食神','舒適區打轉','只挑喜歡的章節讀，難的繞過','只挑舒適區會放大弱項。用 if-then：「先做一題最不想碰的，再回喜歡的」，把難題拆到最小步再開始。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-09','C1','認知類','食神','邊讀邊神遊','想像考上後的事，眼到心不到','神遊代表注意力斷線。起身喝水30秒重啟，回座設一個5–15分鐘的明確小目標，用主動回憶把心拉回文本。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-10','C1','認知類','傷官','嫌教材挑出題','一直挑剔課本/老師講法，沒在吸收','挑剔常是逃避吸收。把吐槽寫到筆記欄，正文先照單全收、做主動回憶；有疑慮標記，留到複習時再驗證。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-11','C1','認知類','傷官','鑽冷門細節','執著考點外的枝節想反駁','先問「這會考嗎」。對照考綱，非考點先略過、記下；把精力放到高頻考點的提取練習上，別被枝節綁住。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-12','C1','認知類','傷官','自以為懂','看過一遍就覺得會了不複習','「看過」不等於會。用提取練習檢驗：闔書默寫或做幾題，寫不出來的才是真正該補的，別讓熟悉感騙了你。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-13','C1','認知類','偏財','貪多開太多書','同類教材買一堆同時翻','多買多開反而更亂。鎖定一套主教材讀通，其餘收起來；一個主題只跟一條主線，讀完用主動回憶確認再換。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-14','C1','認知類','偏財','被外務勾走','讀書時忙別的小事與訊息','雜事勾走的是專注。用「雜事時段」：讀書中想到就寫下，集中到固定時段一次處理，當下只留這一科。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-15','C1','認知類','偏財','傳言式跳讀','聽說哪裡會考就亂跳章節','傳聞式跳讀打亂結構。照原章節序走，聽到的考點記下不立刻動；用考綱與歷屆題判斷權重，而非小道消息。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-16','C1','認知類','正財','過度算分','一直估自己幾分，而非真的讀進去','反覆估分會取代真讀。今天只記「讀完題數、弄懂觀念」，把算分排到每週一次，用過程指標取代結果焦慮。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-17','C1','認知類','正財','患得患失複習','怕忘，一直回頭重看舊內容','怕忘而一直回看效率低。改用間隔複習：依遺忘曲線排到期日，到期才回看一次，其餘時間往前推進度。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-18','C1','認知類','七殺','進度焦慮塞太滿','排到不可能完成的量','塞爆排程必崩。把計畫砍半、留兩成緩衝，用 if-then 設每日量上限；可達成的小計畫比完美計畫更有效。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-19','C1','認知類','七殺','自逼到腦空白','越逼越讀不進、一片空白','越逼越空白是焦慮佔走工作記憶。卡住就離桌走動5分鐘、做幾次慢吐氣呼吸降速，再從一個會的小題重新接上。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-20','C1','認知類','正官','筆記完美癖','花太多時間排版抄漂亮','美化筆記是低效學習。限時抄「自己看得懂的重點」、醜也接受；省下時間改做提取練習，筆記是為了回想不是好看。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-21','C1','認知類','正官','怕錯不敢往下','一處沒全懂就不肯推進度','怕錯而停滯會拖垮全局。先求走完一輪、抓主架構，沒全懂的標問號跳過，第二輪再補（先求80分再求完美）。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-22','C1','認知類','偏印','一題鑽到底','為一個冷僻點查到天荒地老','鑽冷僻點是無底洞。設時限，逾時就記下問人；先把高頻考點用提取練習讀熟，別在低報酬處耗光時間。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-23','C1','認知類','偏印','糾結哪種理解才對','在多種解法間反覆內耗','多解法內耗。先選一種你能算對的用熟，其他記下留複習時比較；能解題的理解，勝過糾結哪個最完美。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-24','C1','認知類','正印','備而不讀','整理工具/計畫卻遲遲沒開始','一直準備卻不開始是拖延。用兩分鐘起步法＋if-then：「鈴一響就讀兩分鐘」，把規劃時間壓到10分鐘內。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C1-25','C1','認知類','正印','等狀態好才讀','老覺得還沒準備好','不必等狀態好。行為先於動機：用兩分鐘起步法直接讀兩分鐘，動起來狀態多半會跟上，別等準備好才開始。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-01','C2','情緒類','比肩','孤立硬撐情緒','難過也不說，自己扛','情緒悶著更重。每天找一個信任的人講一句真實心情，或用表達性書寫把感受寫下來；研究顯示書寫能降低焦慮與反芻。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-02','C2','情緒類','比肩','好強不認累','累到不行還否認','否認疲勞會累積成崩盤。用1–10替疲勞評分，≥7就安排休息；把休息當必要投資，而非軟弱。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-03','C2','情緒類','劫財','一點就炸','急躁易怒，火氣上得快','怒火上來先別反應。做幾次慢吐氣呼吸、離開現場幾分鐘再回應；在情緒高點不下判斷、不對話。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-04','C2','情緒類','劫財','焦躁坐不住','心浮氣躁、靜不下來','焦躁多是身體張力。起身快走或伸展3–5分鐘把躁能釋放，再做配速呼吸降速，然後從一個最小任務切入。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-05','C2','情緒類','食神','用吃紓壓過頭','一焦慮就猛吃','情緒性進食先按暫停。焦慮時先喝水＋走動5分鐘再決定吃；同時找替代出口（書寫、散步），處理情緒本身而非用吃壓。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-06','C2','情緒類','食神','逃進耍廢','情緒一來就追劇逃避','逃避型耍廢越逃越空。設20分鐘限時放鬆鬧鐘，到點回到一個最小任務；用行為活化安排能帶來成就感的小事。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-07','C2','情緒類','傷官','情緒外放遷怒','把壓力發在家人身上','遷怒前先離場。想發作時離開現場10分鐘、做慢呼吸降溫，把壓力寫下來而非倒在家人身上，冷靜後再溝通。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-08','C2','情緒類','傷官','委屈感重','覺得沒人懂、抱怨變多','委屈寫下來比脫口而出有用。用表達性書寫把感受誠實寫出，實證能緩解焦慮與反芻；需要時找人說，而非到處抱怨。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-09','C2','情緒類','偏財','被外界牽動','一則消息就大起大落','易被消息牽動就管理輸入。限定看消息的固定時段、其餘關通知；看到衝擊內容先深呼吸，提醒自己這不影響你的準備。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-10','C2','情緒類','偏財','消費玩樂壓情緒','亂買亂滑來紓壓','衝動消費/滑手機是短效紓壓。設「想買先放24小時」規則，改用散步、書寫等真正能降載的方式處理情緒。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-11','C2','情緒類','正財','患得患失','一直擔心努力會白費','患得患失多在不可控處打轉。列「可控/不可控」兩欄，只投入可控的今日行動；擔心會白費時，回到眼前能做的一步。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-12','C2','情緒類','正財','怕落後同儕','比較後沮喪低落','比較後低落很常見。把基準從同儕改成「昨天的自己」、記錄自己的小進步；減少接觸進度展示，專注自己的軌道。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-13','C2','情緒類','正財','成績焦慮','一次模考差就崩潰','把分數當回饋、不當判決。模考差就記下要補的點當健檢結果；先做一次慢呼吸降焦慮，再用提取練習補弱項。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-14','C2','情緒類','七殺','高壓恐慌','一想到考試就心悸','用認知重評：把加速的心跳重新解讀為身體在幫你供氧、上場前的正常激活；再做3輪 4-7-8 配速呼吸降速。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-15','C2','情緒類','七殺','自我攻擊','不停罵自己不夠好','自我攻擊用自我疼惜化解。把罵自己的話改寫成「你會對好朋友說的話」，就事論事找下一步，而非否定整個人。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-16','C2','情緒類','七殺','倒數窒息感','倒數逼近喘不過氣','倒數窒息是被整體壓垮。用紙遮住整體倒數，只看「今天這一格」要做的事；把大範圍拆成今日可完成的小目標。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-17','C2','情緒類','正官','怕辜負期待','背著家人期望喘不過','期待的重量先分清歸屬。寫下「我的目標 vs 別人的期待」兩欄，把不屬於你的放下；與家人具體溝通你需要的支持。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-18','C2','情緒類','正官','過度自責','一個錯內疚一整天','一錯內疚整天會癱瘓。寫下「錯在哪＋下次怎麼做」然後翻頁；用自我疼惜的語氣，把自責換成具體可改的一步。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-19','C2','情緒類','正官','壓抑不敢示弱','硬撐微笑不喊累','壓抑硬撐遲早外溢。允許自己每週一段「擺爛時段」正當休息，並對信任的人坦白狀態；示弱不是失敗，是讓你撐得久。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-20','C2','情緒類','偏印','反芻負面念頭','同一個擔憂繞圈打轉','反芻會原地空轉。用「擔憂時段」：設15分鐘專門想，其餘時間想到就寫下、延後；搭配把注意力放回當下的活動。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-21','C2','情緒類','偏印','莫名空虛','提不起勁、疏離','空虛時用行為活化破冰。先做一件5分鐘、能帶來完成感或意義的小事（連結、助人、整理），用行動帶回情緒。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-22','C2','情緒類','偏印','半夜胡思','躺床放大焦慮','半夜胡思先清空大腦。把腦中事寫到紙上「都記下了明天處理」；躺20分鐘睡不著就起身做無聊的事、有睡意再回床（刺激控制）。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-23','C2','情緒類','正印','討保證才安心','一直找人要安慰','一直討保證會更不安。先自己寫三句安撫＋一個可控行動，再去求證；練習容忍不確定，把安全感建立在行動而非他人保證。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-24','C2','情緒類','正印','戀舒適逃現實','賴在被窩不面對','賴床逃避用最小啟動破解。起床先開窗、喝水、腳落地，用晨光與身體啟動；不必等想面對，先動兩分鐘。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C2-25','C2','情緒類','正印','被動等情緒過去','消沉時什麼都不做','消沉時被動等待會更沉。用行為活化安排一件固定小活動（散步、出門曬光），先動身體再等情緒，不靠「等它過去」。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-01','C3','行為類','比肩','硬拚不休息','連坐數小時不離桌','久坐硬拚效率遞減。用番茄鐘：每50分鐘強制起身5–10分；把休息排進表當必做，有節奏的張弛比硬撐更持久。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-02','C3','行為類','比肩','拒絕現成方法','不照任何讀書範本','全自創常是繞路。先借一個有實證的框架（主動回憶＋間隔複習）用一週，有數據再微調，別從零硬試。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-03','C3','行為類','比肩','單打獨鬥','拒絕讀書會與共學','完全單打會少了回饋。保留每週一次跟人對答案或討論，用別人的提問檢驗你的盲點；社會支持也能降壓。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-04','C3','行為類','劫財','衝動改計畫','三天兩頭換讀法','一直換讀法等於沒方法。給一套計畫至少跑滿7天再用數據評估；頻繁改動會抹掉累積，先穩定再優化。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-05','C3','行為類','劫財','開頭多收尾少','啟動很多卻沒完成','開頭多收尾少。立規則「完成一項才准開下一項」，用 if-then 把任務切成可立刻完成的小步，先收尾再啟動新的。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-06','C3','行為類','劫財','亂花時間','被臨時起意帶走','被臨時起意帶走時間。前一晚寫好「今日三件必做」先清掉；用 if-then 預設何時做什麼，減少臨場決定的耗損。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-07','C3','行為類','食神','拖延享樂','先玩再說，一直延後','先玩再讀容易無限延。用「先讀25分換5分玩」固定順序＋誘惑綁定；把娛樂當完成後的獎勵，而非開頭。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-08','C3','行為類','食神','過度休息','休息一下變一下午','休息容易擴張。休息一律設鬧鐘、鈴響回桌；用刺激控制——休息離開書桌、回桌只做事，讓界線清楚。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-09','C3','行為類','食神','磨蹭暖機久','拖很久才開始','暖機太久是啟動門檻太高。用兩分鐘起步法：只要求做兩分鐘，動起來慣性會接手；把第一步縮到不可能失敗。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-10','C3','行為類','傷官','鑽捷徑跳基礎','只找考古題捷徑跳過基本功','跳過基礎抄捷徑會崩。基礎與題技各排固定時段；先把核心觀念用主動回憶讀通，再練題型，根基穩捷徑才有用。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-11','C3','行為類','傷官','半途想自創','嫌方法老、半路棄做','半路想自創常是逃避。先照標準方法做完一輪、看到成效再改良；承諾跑完一個完整週期，別在中途換軌。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-12','C3','行為類','傷官','愛現耗時','花時間做漂亮輸出給人看','美化輸出給人看會吃時間。產出先求完成、後求美化；把展示欲導向真正的提取練習與題數，而非排版好看。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-13','C3','行為類','偏財','多頭進行','同時搞太多項目','多頭並進樣樣淺。限制同時進行最多兩項、其餘排隊；用單工把心力集中，完成一項再開下一項。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-14','C3','行為類','偏財','被娛樂帶走','滑手機停不下來','滑手機停不下是設計使然。App 設使用時限、登出或移到深層資料夾，手機放遠；讀書時用刺激控制隔離誘因。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-15','C3','行為類','偏財','追新工具','一直換 app/文具不讀','一直換工具是高級拖延。工具凍結一個月只用現有的；把「找更好工具」的力氣，改投到實際做題與回想上。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-16','C3','行為類','正財','規劃不執行','表做很細卻沒動','規劃很細卻不動。把規劃時間壓到執行的1/5以內，用 if-then 直接把第一步排進今天某個時刻，先做再修。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-17','C3','行為類','正財','算投報才動','計較划不划算才開始','算划不划算會卡在起點。不評估，直接做完「最小一步」；行動會帶來資訊，先動起來再判斷值不值得。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-18','C3','行為類','七殺','暴衝爆量','一天塞爆、隔天崩盤','暴衝爆量隔天崩。設每日量上限、超過不准，留兩成緩衝；穩定的可持續配速，長期產出遠勝忽快忽崩。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-19','C3','行為類','七殺','報復性熬夜趕','白天拖、晚上狂趕','報復性熬夜趕傷恢復。設「熄燈線」、過點未完就停；固定起床時間穩住生理節律（刺激控制），白天才追得回。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-20','C3','行為類','正官','流程僵化','非照固定順序不可，卡住停擺','流程僵化一卡就停擺。允許「跳關」，卡住先做下一塊、回頭再補；把固定順序當參考而非鐵律，維持前進。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-21','C3','行為類','正官','過度檢查','反覆核對不前進','反覆檢查是焦慮找確定。立規則「最多檢查兩遍就交」，用計時逼自己相信第一判斷；把省下的時間拿去多做一題。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-22','C3','行為類','偏印','想流程想到不做','計畫想半天卻沒動手','想流程想到不做。想最多5分鐘就強制執行，用 if-then 把計畫變成「此刻就做第一步」；規劃的安全感不能取代行動。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-23','C3','行為類','偏印','卡題硬鑽','一題卡住不肯跳過','卡題硬鑽會卡死整段。設「卡20分鐘就跳下一題」、標記回頭再攻；先維持前進，難題留到狀態好時集中處理。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-24','C3','行為類','正印','等準備好才動','工具不齊不開始','工具不齊就不開始是藉口。用現有的先開始、缺的邊做邊補；真正需要的只是動手，完美條件是加分不是前提。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C3-25','C3','行為類','正印','賴床晚啟動','一早就荒廢掉','賴床荒廢整個早上。鬧鐘響「腳先落地＋冷水洗臉＋開窗光照」啟動身體；用 if-then 預設起床後第一個動作。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-01','C4','生理類','比肩','逞強不補眠','硬撐少睡','少睡會直接砍記憶與專注。固定就寢與起床時間（CBT-I 核心），別用犧牲睡眠換時數；睡飽的腦讀得更快更牢。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-02','C4','生理類','比肩','久坐僵硬','不肯停下伸展','久坐讓身體僵、腦變鈍。每小時起身伸展1–2分鐘、動開肩頸腰背；規律微活動能維持循環與專注。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-03','C4','生理類','劫財','飲食急亂','邊讀邊扒飯、消化差','邊讀邊扒飯傷消化也分心。吃飯離桌專心15分鐘、細嚼慢嚥；規律定時進食穩住血糖，腦力才有支撐。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-04','C4','生理類','劫財','過量咖啡因','靠提神飲料硬撐','過量咖啡因會反噬睡眠。下午後改無咖啡因、別靠提神飲料硬撐；真正解疲勞的是規律睡眠，不是越喝越多。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-05','C4','生理類','食神','嘴饞亂吃','零食不停、血糖亂','零食不停讓血糖起伏、更累。備堅果/水果取代甜食、定時正餐；穩定血糖有助維持專注與情緒。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-06','C4','生理類','食神','慵懶不動','整天不運動、身體鈍','整天不動身體會鈍。每天10–20分鐘快走或伸展、排進固定時段；規律活動能改善精神、睡眠與情緒，CP值很高。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-07','C4','生理類','傷官','作息任性','想睡才睡、日夜顛倒','日夜顛倒先穩「起床時間」。固定每天同一時間起床＋晨光照射校準生理時鐘（CBT-I），比先調就寢更有效。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-08','C4','生理類','傷官','硬抗身體訊號','痛了累了還撐','硬抗痛與累會累積成病。出現警訊先休10分鐘、補水伸展；身體訊號是資料不是軟弱，連續多日不適請就醫。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-09','C4','生理類','偏財','熬夜玩耗體力','娛樂到很晚','熬夜玩透支隔天。設「螢幕宵禁」時間、把娛樂提前到白天；睡前一小時離螢幕、調暗燈光，保護睡眠節律。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-10','C4','生理類','偏財','三餐不定','忙外務忘了吃','忙到忘了吃會掉專注。設用餐鬧鐘、定時進食；每餐有蛋白質與蔬菜，別讓空腹太久造成血糖與情緒波動。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-11','C4','生理類','正財','壓縮睡眠換時間','捨不得休息硬省','省睡換時間是賠本。把睡眠當必要投資排進表（CBT-I）；睡眠不足會降低記憶與效率，省下的時間反而被浪費。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-12','C4','生理類','正財','省錢虧待身體','亂吃省伙食','亂吃省伙食會虧待腦力。一餐至少保證蛋白質＋蔬菜；穩定均衡的飲食是專注與情緒的地基，別在這裡省。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-13','C4','生理類','正財','肩頸緊繃累積','長期緊繃沒放鬆','長期肩頸緊繃要主動放鬆。每天熱敷/伸展肩頸5分鐘、把螢幕墊到視線高度；久不退或頭痛頻繁請就醫評估。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-14','C4','生理類','七殺','壓力性失眠','緊張到睡不著','壓力性失眠用刺激控制：床只用來睡、睡前1小時離螢幕並放鬆；睡前把擔憂寫下清空大腦，長期失眠建議尋求專業。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-15','C4','生理類','七殺','心悸腸胃緊','壓力跑到身體上','壓力跑到身體（心悸、腸胃緊）。做腹式/配速呼吸降交感神經、飲食清淡少刺激；若心悸頻繁或持續、合併不適請就醫。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-16','C4','生理類','七殺','透支到生病','撐到免疫崩潰','撐到免疫崩潰得不償失。出現感冒徵兆就減量休息、補眠補水；預防性踩煞車，別等病倒，身體穩了效率才穩。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-17','C4','生理類','正官','規律過頭緊繃','一打亂就身體緊張','太要求規律、一亂就緊繃。容許彈性、亂了不自責；把計畫當方向而非鐵律，並用慢呼吸/伸展鬆開累積的張力。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-18','C4','生理類','正官','憋著不喝水如廁','怕中斷不敢停','憋著不喝水如廁傷身又分心。每節下課固定喝水、如廁；適度補水有助專注，別用「怕中斷」犧牲基本需求。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-19','C4','生理類','正官','姿勢僵直腰背痛','端正久坐不動','端正久坐不動仍會腰背痛。重點是「常換姿勢」：每小時起身、加腰靠、伸展；久痛不退建議就醫評估。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-20','C4','生理類','偏印','入睡困難','躺床腦子關不掉','躺床腦關不掉。睡前把念頭寫到紙上清空、做配速呼吸；躺20分鐘睡不著就起身做無聊的事、有睡意再回床（刺激控制）。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-21','C4','生理類','偏印','慢性疲勞','睡了還是累、虛','睡了還累多是品質或節律問題。固定起床＋白天曬光＋規律三餐，別靠補眠硬補；長期疲勞不退請就醫檢查。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-22','C4','生理類','偏印','食慾不振','心思重、吃不下','心思重而吃不下。少量多餐、選清淡好入口的食物，別逼大餐；同時處理壓力源，食慾長期不振或明顯掉體重請就醫。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-23','C4','生理類','正印','嗜睡賴床','睡很多仍懶洋洋','睡很多仍懶，常是節律亂。固定起床時間、起床立刻接觸光照與活動；避免賴床貪睡，規律比睡長更能提神。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-24','C4','生理類','正印','久坐代謝低','整天窩著不動','整天窩著代謝與精神都低。每天安排一次戶外活動或快走；規律地動起來能改善能量、睡眠與情緒。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C4-25','C4','生理類','正印','依賴環境才能讀','離開暖被就無力','只在暖被裡才讀是環境制約。改用刺激控制：固定到書桌讀、床只用來睡；讓「書桌＝讀書」建立新的啟動連結。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-01','C5','社交類','比肩','與同儕較勁','暗中較高下傷感情','暗中較勁兩敗俱傷。把對手當隊友，共享一份筆記或互相出題；合作式學習能減壓，也讓你看見自己的盲點。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-02','C5','社交類','比肩','不肯示弱求助','有問題不問同學','不問會讓小問題拖大。用 if-then：「卡住15分鐘就問同學一題」；把問題寫成具體一句話，發問是聰明不是示弱。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-03','C5','社交類','比肩','孤狼讀書','完全切斷社交','完全斷社交會耗損心理能量。保留每週一次低負擔的短聚或通話；社會支持本身就能緩衝壓力。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-04','C5','社交類','劫財','易與人摩擦','急躁、說話衝','說話衝多在情緒高點。回訊息前先放10分鐘、做幾次深呼吸；冷靜後再回應，能少掉很多不必要的摩擦。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-05','C5','社交類','劫財','被朋友拉走','一揪就跑、時間被佔','一揪就跑會吃掉時間。把社交集中到週末一次，平日用 if-then 婉拒；先守住讀書時段，再安排相聚。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-06','C5','社交類','劫財','來者不拒被耗','幫忙幫到自己沒時間','來者不拒會被掏空。練習一句界線：「我這週滿了」；幫忙前先確認自己的時間，設界線不是冷漠。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-07','C5','社交類','食神','聊到忘讀書','一開聊就收不住','一開聊就收不住。設聊天限時鬧鐘，或約「讀完這段再聊」；把社交當完成後的獎勵，維持讀書節奏。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-08','C5','社交類','食神','愛揪吃喝玩','飯局聚會太多','聚會太多會排擠進度。一週社交額度設兩次、其餘婉拒；有意識地選擇，而非有揪就去。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-09','C5','社交類','食神','過度迎合','不好意思拒絕','不好意思拒絕會累積壓力。用漸進練習：先婉拒一次小邀約；準備一句固定的拒絕語，練多了就不彆扭。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-10','C5','社交類','傷官','言語得罪人','直言批評惹爭執','直言惹爭執。開口前自問「必要嗎、善意嗎、現在嗎」；把批評換成提問或我訊息，先聽再說。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-11','C5','社交類','傷官','頂撞師長','跟老師槓上','與師長槓上無益學習。不同意先記下、私下再談；把焦點放回「我要學到什麼」，而非爭對錯。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-12','C5','社交類','傷官','群組刷存在','花時間刷表現','群組刷存在很耗時。把群組設固定時段才看、關通知；把刷表現的力氣改投到實際做題與回想。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-13','C5','社交類','偏財','社交太廣','群組/應酬太多','社交面太廣會分散心力。退掉無關群組、精簡到少數真誠關係；備考期重質不重量。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-14','C5','社交類','偏財','追別人動態','被八卦消息帶走','追別人動態被帶走。限定看社群的時段、取消會引發比較的追蹤；把注意力收回自己的軌道。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-15','C5','社交類','偏財','人情花費壓力','應酬破財又破時間','應酬破財又破時間。婉拒非必要邀約、設社交預算與額度；把資源留給真正重要的關係與目標。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-16','C5','社交類','正財','計較人際得失','衡量誰對我有用','計較誰有用會讓關係變累。單純維繫兩三個真誠關係就好；支持感來自真誠互動，而非利益盤算。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-17','C5','社交類','正財','怕欠人情不求助','寧可自己卡著','怕欠人情而硬撐。把求助看成「聰明用資源」、日後再回報；會求助的人通常走得更快、更省力。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-18','C5','社交類','七殺','對人防備緊張','怕被評價不敢互動','怕被評價而緊張。用漸進暴露：從點頭問好、傳一句訊息等低風險互動開始，逐步累積「沒事」的經驗。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-19','C5','社交類','七殺','壓力下對人兇','壓力大就衝突','壓力大就對人兇。壓力高時減少需協調的事、先降載；感覺要爆先離場深呼吸，別在高點處理人際。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-20','C5','社交類','正官','太在意眼光','怕丟臉不敢發問','太在意眼光而不敢問。提醒自己「發問是常態、多數人沒那麼在意你」；用漸進暴露，先在低壓對象練習開口。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-21','C5','社交類','正官','被責任綁住','攬太多群體事務','攬太多群體事務會被綁死。一次只接一個義務、其餘婉拒；把界線講清楚，保護自己的核心時間。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-22','C5','社交類','偏印','社交退縮','越壓力越躲人','越壓力越躲人會更孤立。用漸進暴露＋行為活化：每天一次低壓互動（傳訊也算），從最小的一步重建連結。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-23','C5','社交類','偏印','想太多不敢開口','演練到最後沒行動','演練到最後沒行動。把目標縮到「先傳出第一句」；行動先於完美，開口後對話多半會自然接上。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-24','C5','社交類','正印','過度依附一人','黏著特定人求安心','只黏一個人風險高。刻意擴展到兩三個支持來源；分散依附讓你更穩，也不會壓垮對方。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C5-25','C5','社交類','正印','被動等人主動','不連絡漸漸孤立','被動等人會漸漸孤立。用 if-then：「每週主動約一次」；一個小小的主動，就能打斷越縮越孤的循環。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-01','C6','人生結構類','比肩','只認一條路','非這條不可、沒有備案','孤注一擲會放大恐懼。寫下一個 Plan B，讓「萬一」有出口；有備案反而能更穩地專注在主線上。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-02','C6','人生結構類','比肩','抗拒他人規劃','誰勸都不聽','誰勸都不聽會錯過資訊。找一位走過這條路的人聊30分鐘、只蒐集資料不必照做；多一個視角，選擇更清楚。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-03','C6','人生結構類','劫財','頻換目標','一遇挫就想轉跑道','一挫就想轉跑道會空轉。給現目標一個固定檢視期（如3個月）再決定；低潮時不換軌，用數據而非情緒判斷。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-04','C6','人生結構類','劫財','衝動放棄','想撂挑子','想撂挑子時先別決定。撐過48小時、睡飽再看；重大決定不在情緒谷底做，先降載恢復再評估。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-05','C6','人生結構類','食神','得過且過','對未來無所謂、隨它去','對未來無所謂常是耗竭的偽裝。用行為活化設一個3個月小目標，先做能感到進展的小事，方向感會回來。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-06','C6','人生結構類','食神','逃避長遠','只想享當下不想規劃','只想享當下、逃避長遠。每月花20分鐘看一次大方向就好、其餘專注當下；把遙遠目標拆成本季可做的事。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-07','C6','人生結構類','傷官','質疑努力意義','「讀這幹嘛」反骨','「讀這幹嘛」時重連動機。寫下你要這結果的三個具體理由（價值澄清）；把抽象意義換成今天的一個小行動。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-08','C6','人生結構類','傷官','反體制虛無','覺得制度不公乾脆擺爛','覺得制度不公而擺爛，傷的是自己。分清「能改的 vs 只能接受的」，把力氣投在可控處；不滿可以化成具體行動。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-09','C6','人生結構類','偏財','機會太多難取捨','什麼都想要','什麼都想要會樣樣淺。用「今年只選一件」聚焦、其餘排隊；依你的核心價值排序，先把一條走深。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-10','C6','人生結構類','偏財','被外在標準牽走','追別人定義的成功','追別人定義的成功會空。寫下自己的成功定義三條，用它當指南針；減少接觸會引發比較的訊息。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-11','C6','人生結構類','正財','只問值不值得','過度看重結果回報','只問值不值得會卡在起點。記錄過程中已獲得的能力與成長、不只看結果；把焦點從報酬移到「我學到什麼」。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-12','C6','人生結構類','正財','害怕沉沒成本','投入太多不敢轉彎','怕浪費已投入而不敢轉彎（沉沒成本）。用「從今天起的最佳選擇」思考；過去投入不該綁住未來決定。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-13','C6','人生結構類','正財','安全感焦慮','怕沒保障不敢冒險','怕沒保障而不敢動。列「最壞情況＋我能怎麼應對」，把未知變成可處理；降低不確定後，行動門檻就低了。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-14','C6','人生結構類','七殺','成敗極端','全押一次定生死','把一次考試當生死，壓力會爆。提醒自己這是多次機會之一、可重來；把「定生死」重新框成「一段過程」。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-15','C6','人生結構類','七殺','價值綁成敗','沒上＝我沒用','「沒上＝我沒用」是把價值綁成敗。刻意分開「考試結果」與「我的價值」；你的能力、關係、努力不會因一次歸零。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-16','C6','人生結構類','七殺','倒數恐懼','被人生時程逼瘋','被人生時程逼瘋。每個人時程不同，把目光從「落後多少」拉回「本季能做什麼」；年齡只是數字，方向對就好。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-17','C6','人生結構類','正官','背負應該的人生','照別人劇本走得累','照別人劇本走會累。列「我想要 vs 應該」各三條對照，把不屬於你的放下；為自己保留一點選擇權。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-18','C6','人生結構類','正官','怕走錯不敢選','卡在決定動彈不得','怕走錯而卡住。設決策期限、到期就選；多數選擇可邊走邊修，先選一個行動，資訊會在路上出現。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-19','C6','人生結構類','正官','完美藍圖癱瘓','要規劃到完美才動','要規劃到完美才動會癱瘓。先訂一版「可改的草案」就開始；計畫永遠不完美，執行才帶來進展。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-20','C6','人生結構類','偏印','存在性空虛','反覆問活著為何','反覆問活著為何時先連結。做一件助人或有意義的小事，用行動接回意義感；同時顧好睡眠與作息基礎。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-21','C6','人生結構類','偏印','過度內省','想人生想到無法生活','想人生想到無法生活。把大哉問交給「每週一次省思時段」、其餘回到具體小行動；思考過量時用身體活動拉回當下。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-22','C6','人生結構類','偏印','脫節幻想','沉在「如果」裡','沉在「如果」的幻想裡。每天落實一個具體小行動，把能量從想像導向現實；用完成的小事證明自己在前進。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-23','C6','人生結構類','正印','等貴人時機','被動盼外援','被動等貴人會原地停。先主動踏出一步（投履歷、開口問、做一題）；機會多半在行動之後才出現。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-24','C6','人生結構類','正印','賴熟悉不敢變','怕離開舒適圈','怕離開舒適圈。用漸進暴露：做一個低風險的新嘗試，成功一次再加一點；改變從小到不怕的一步開始。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C6-25','C6','人生結構類','正印','沒主見','依賴他人定義方向','沒主見、依賴他人定方向。先自己寫一版人生草圖（就算粗糙）再去徵詢；有了初稿，別人的意見才是參考不是指令。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-01','C7','恢復失衡類','比肩','不准自己休息','休息有罪惡感','休息有罪惡感會讓你休不好。把休息排進表、當任務完成；「恢復」是維持表現的必要環節，不是偷懶。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-02','C7','恢復失衡類','比肩','硬撐式恢復','累到極限才停','撐到極限才停會崩。改「預防性休息」：在還沒透支前就主動停；有節奏的張弛比硬撐到底更可持續。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-03','C7','恢復失衡類','比肩','不肯放慢','一直全速不降配速','一直全速會燒乾。每週安排一天「降速日」刻意放慢；持久戰需要配速，不是每天全力衝刺。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-04','C7','恢復失衡類','劫財','休息停不下','滑手機反而更累','滑手機式休息沒讓腦歇。改做離螢幕的活動（散步、伸展、閉眼）；真恢復是讓神經降速，不是繼續接收資訊。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-05','C7','恢復失衡類','劫財','報復性放縱','一放鬆就過頭','一放鬆就過頭。設放鬆的「時間與內容上限」＋鬧鐘；用刺激控制把娛樂限定在固定時段，避免報復性失控。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-06','C7','恢復失衡類','劫財','碎片休息無效','一直被打斷','一直被打斷的休息無效。給自己一段30分鐘、不被打擾、不碰手機的完整恢復；品質比次數重要。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-07','C7','恢復失衡類','食神','休息變失控','一耍廢就一整天','一耍廢就一整天。娛樂限時＋鬧鐘，結束就接一個最小任務；用 if-then 設定何時回到正事。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-08','C7','恢復失衡類','食神','追享樂越玩越空','一直追刺激回血','追刺激越玩越空。改成散步、小睡等「真恢復」；高刺激娛樂會讓神經更累，低刺激的留白才補得回電。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-09','C7','恢復失衡類','食神','玩完更不想動','拖延恢復正事','玩完更不想動。先做最小一步正事（兩分鐘起步）再玩，或把玩當完成後的獎勵，避免恢復變拖延。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-10','C7','恢復失衡類','傷官','抗拒恢復節奏','嫌規律無聊不照做','嫌規律無聊而不照做。給恢復加點變化但保留底線（固定睡眠、每日活動）；可彈性換內容，但別放掉地基。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-11','C7','恢復失衡類','傷官','情緒化擺爛','一不爽就報復式耍廢','一不爽就報復式耍廢。不爽時先動身體10分鐘把情緒代謝掉、再決定怎麼休；用行動打斷情緒化的擺爛。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-12','C7','恢復失衡類','傷官','用刺激填空虛','重口味娛樂越看越累','重口味娛樂越看越累。換低刺激活動讓神經降載（散步、發呆、聽輕音樂）；空虛用連結與小成就感補，而非更強刺激。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-13','C7','恢復失衡類','偏財','恢復被瓜分','休息也在忙雜事','休息還在忙雜事＝沒休。劃出一段「純恢復、不被佔用」的時間；把雜事集中到別的時段，讓休息真的是休息。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-14','C7','恢復失衡類','偏財','多元娛樂更累','樣樣沾、沒真歇','樣樣沾沒真歇。一次只做一種放鬆、單工地休；切換太多反而更累，專心地休一件事更能回血。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-15','C7','恢復失衡類','偏財','社交式休息','應酬當休息更耗','應酬當休息更耗能。安排一段獨處安靜的恢復；社交有其價值，但若它讓你更累，就先補一段不需應對人的時間。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-16','C7','恢復失衡類','正財','捨不得花時間','覺得休息浪費','覺得休息浪費時間。把恢復重新框成「提升效率的投資」；睡眠與休息能改善記憶與專注，省掉它反而更慢。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-17','C7','恢復失衡類','正財','休息也算進度','放鬆時仍焦慮','放鬆時仍焦慮、像在算進度。休息時刻意做一件「純無產出」的事，並把待辦寫下清空大腦，允許自己這段不生產。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-18','C7','恢復失衡類','七殺','緊到無法放鬆','停不下來','緊到停不下來。做10分鐘漸進式肌肉放鬆或配速呼吸，讓身體學會降速；緊繃是可以練習鬆開的。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-19','C7','恢復失衡類','七殺','恢復也設高標','連睡覺都要求完美','連睡覺都要求完美反而睡不好。放下執念，「躺著閉眼也算休息」；對睡眠的焦慮會惡化失眠，降低標準才睡得著。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-20','C7','恢復失衡類','正官','罪惡感不敢真休','休了還自責','休了還自責。給自己一張「休息許可證」：這段是被允許的；提醒自己硬撐到崩潰才是真浪費，休完效率更好。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-21','C7','恢復失衡類','正官','死板恢復流程','非某種方式不可','非某種方式不可、太死板。準備兩三種替代放鬆法輪流；恢復的重點是有效降速，而非固定儀式。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-22','C7','恢復失衡類','偏印','腦不停轉','越歇越想','越歇腦越轉。用「身體型活動」把注意力外移（散步、伸展、做家事）；睡前把念頭寫下清空，給大腦一個單純焦點。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-23','C7','恢復失衡類','偏印','獨自悶著','越宅越沉','越宅越沉。出門曬光＋一次短互動，用行為活化打斷下沉；光照與連結對情緒有實際幫助。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-24','C7','恢復失衡類','正印','過度休息停滯','一歇就不想動','一歇就不想動（停滯）。休息設明確結束點＋下一個小動作，用 if-then 接回行動；避免恢復變成癱在原地。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C7-25','C7','恢復失衡類','正印','依賴特定方式','沒它就焦慮','沒某個方式就焦慮。刻意準備2–3種替代放鬆法練習適應；減少對單一方式的依賴，恢復才更有韌性。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-01','C8','長期壓力崩潰類','比肩','硬撐到燃盡','不求援撐到垮','硬撐到燃盡前先求援。主動找一個人講現況＋請求支援；這類過載不該再用硬撐解，先穩住睡眠、飲食與人際支持。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-02','C8','長期壓力崩潰類','比肩','否認已經崩','嘴硬說沒事','嘴硬說沒事會錯過煞車點。誠實自評，需要就停；長期壓力接近過載時，承認並求助才是出路，別獨自硬撐。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-03','C8','長期壓力崩潰類','劫財','崩潰邊緣亂衝','病急亂投醫亂改','崩潰邊緣亂改更亂。危機時先「穩定、不做大改動」：砍掉非必要任務、先睡飽吃好，等情緒過了再談調整。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-04','C8','長期壓力崩潰類','劫財','情緒潰堤','一爆不可收','情緒潰堤先求安全。離開現場、冷水洗臉或慢吐氣呼吸降載，找人陪；今天進度先放一邊，穩定優先。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-05','C8','長期壓力崩潰類','食神','擺爛麻木','什麼都不想做','什麼都不想做時，把目標縮到最小。只要求完成一件1分鐘的事（下床、喝水）；別逼振作，先動最小一步，並找人陪。',true) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-06','C8','長期壓力崩潰類','食神','享樂麻痺','暴吃暴看逃避','用暴吃暴看麻痺崩潰。找一個人陪、別獨自麻痺；先穩住睡眠與飲食，把逃避換成一個能被聽見的對話。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-07','C8','長期壓力崩潰類','傷官','怨懟爆發','遷怒全世界','遷怒全世界前先離場。把怒寫出來、暫離人群、動身體降溫；這是過載的訊號，之後安排真正的減載與休息。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-08','C8','長期壓力崩潰類','傷官','自毀式叛逆','乾脆全放棄','「乾脆全放棄」時先別退出。承諾「只休3天、不做永久決定」；長期壓力會扭曲判斷，先恢復再決定方向，並找人談。',true) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-09','C8','長期壓力崩潰類','偏財','顧此失彼','全面失控分崩','全面失控時做減法。只保留一件最重要的事先穩住，其餘暫時放下或請人分擔；找回一點掌控感再逐步加回。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-10','C8','長期壓力崩潰類','偏財','逃進瞎忙','用外務麻痺崩潰','用瞎忙麻痺崩潰。停下來，寫出真正的壓力源；忙碌會蓋住問題，先辨識再處理，並大幅降低非必要任務。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-11','C8','長期壓力崩潰類','正財','算到掏空','計較到精疲力竭','計較到精疲力竭。暫停評估、先恢復體力（睡飽、吃好、休息）；耗竭時數字算不準，身心穩了再回頭規劃。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-12','C8','長期壓力崩潰類','正財','全盤皆輸的恐慌','覺得一切要完','「一切要完」多是災難化。把真實後果寫下來，多半沒想像糟；先做一次慢呼吸降焦慮，再處理眼前最小可控的一步。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-13','C8','長期壓力崩潰類','正財','沉沒成本綁死','撐著不敢停反更崩','怕浪費已投入而硬撐到更崩。允許「策略性暫停」止損；停下不等於放棄，先保住身心，再決定要不要繼續。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-14','C8','長期壓力崩潰類','七殺','完全耗竭(burnout)','身心皆空、燒乾','完全耗竭需要的是真正停下。強制休息數日、大幅減載、穩定睡眠飲食；若休息後仍長期空乾，請尋求專業協助。',true) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-15','C8','長期壓力崩潰類','七殺','恐慌發作','心悸發抖失控','恐慌發作時用 grounding：說出眼前5看到、4聽到、3摸到…，搭配慢吐氣呼吸，找人陪；它會過去，反覆發作請就醫評估。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-16','C8','長期壓力崩潰類','七殺','自傷念頭','嚴重自責、想消失','出現想消失/自傷的念頭，代表你承受得太久太重，這不是你的錯。請現在就不要獨處，聯絡信任的人陪你；務必撥打求助專線或尋求專業，你值得被接住。',true) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-17','C8','長期壓力崩潰類','正官','責任壓垮停擺','扛太多整個當機','扛太多整個當機。卸下可延後的責任、只留核心一件；告訴一位關鍵的人你需要喘息，把過載分擔出去。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-18','C8','長期壓力崩潰類','正官','怕讓所有人失望','窒息到動彈不得','怕讓所有人失望到動彈不得。告訴一位關鍵的人你需要喘息空間；你無法滿足所有期待，先照顧自己才撐得住。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-19','C8','長期壓力崩潰類','正官','失序自責','一切失控、規範崩解','一切失控、規律崩解。先重建一個最小錨點（固定起床＋一餐），從一件能掌控的小事重新長出秩序，別求一次到位。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-20','C8','長期壓力崩潰類','偏印','抽離麻木','像隔層玻璃看世界','像隔層玻璃的抽離感。用 grounding 把自己拉回此刻（踩地、摸物、說出眼前東西）＋規律作息；持續或頻繁請尋求專業評估。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-21','C8','長期壓力崩潰類','偏印','反芻到失眠','整夜轉不停','反芻到整夜睡不著。起身把念頭寫到紙上清空，離床做無聊的事、有睡意再回（刺激控制）；長期失眠請尋求專業協助。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-22','C8','長期壓力崩潰類','偏印','深度封閉','與世隔絕','與世隔絕會更沉。每天強制一次對外連結（傳訊也算）＋出門曬光；封閉時更需要一點點連結，並考慮尋求支持。',true) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-23','C8','長期壓力崩潰類','正印','退行依賴','退回什麼都要人','退回什麼都要人時，保留一件自理。接受協助的同時，每天做一件自己能完成的小事，慢慢把自主感長回來。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-24','C8','長期壓力崩潰類','正印','失去動力','連起床都難','連起床都難，把目標縮到「下床＋喝水」。這常是耗竭或低潮、不是意志問題；找人陪、補休息很重要，若長期動力歸零請尋求專業協助。',true) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
insert into symptom(id,category_code,category_name,ten_god,name,common,recovery,is_care) values ('C8-25','C8','長期壓力崩潰類','正印','過度求庇護','躲回家不面對','躲回家不面對。在安全的環境裡設一個微小的重啟步驟（出門走五分鐘、做一題）；先讓自己安定，再一步步往外。',false) on conflict (id) do update set ten_god=excluded.ten_god,recovery=excluded.recovery,is_care=excluded.is_care;
