-- ============================================================
-- SoFa Engine｜八字×農民曆・考生症狀資料庫（十神平均分布・實證回穩之道版）
-- Supabase / PostgreSQL：schema + seed + 干支→十神 函式
-- 邏輯：本命日主 × 流日干支 → 引動十神 → 對應症狀(每神20筆) → 實證回穩之道
-- 注意：八字→症狀對應無科學實證，定位為自我覺察；is_care 高關懷條目須保留求助出口。
create extension if not exists "pgcrypto";

create table if not exists ten_god(
  name text primary key, god_group text not null, stress smallint not null, direction text);
create table if not exists heavenly_stem(stem char(1) primary key, wuxing_idx smallint, yin_yang smallint);
create table if not exists earthly_branch(branch char(1) primary key, hidden text[] not null);
create table if not exists symptom(
  id text primary key, category_code char(2) not null, category_name text not null,
  ten_god text not null references ten_god(name), name text not null,
  common text not null, recovery text not null, is_care boolean not null default false);
create index if not exists idx_symptom_god on symptom(ten_god);
create index if not exists idx_symptom_cat on symptom(category_code);


-- seed: ten_god

-- seed: heavenly_stem

-- seed: earthly_branch

-- seed: symptom (200)

-- 干支→十神 函式（木0火1土2金3水4；財/官/印 異陰陽=正、同=偏(七殺)）
create or replace function ten_god(day_master char(1), target char(1))
returns text language plpgsql immutable as $$
declare dw int; dy int; tw int; ty int; same boolean;
begin
  select wuxing_idx,yin_yang into dw,dy from heavenly_stem where stem=day_master;
  select wuxing_idx,yin_yang into tw,ty from heavenly_stem where stem=target;
  if dw is null or tw is null then return null; end if;
  same:=(dy=ty);
  if tw=dw then return case when same then '比肩' else '劫財' end;
  elsif (dw+1)%5=tw then return case when same then '食神' else '傷官' end;
  elsif (dw+2)%5=tw then return case when same then '偏財' else '正財' end;
  elsif (tw+2)%5=dw then return case when same then '七殺' else '正官' end;
  else return case when same then '偏印' else '正印' end; end if;
end; $$;

create or replace function gods_triggered(day_master char(1), day_stem char(1), day_branch char(1))
returns text[] language sql stable as $$
  select array_remove(array[ ten_god(day_master,day_stem),
    ten_god(day_master,(select hidden[1] from earthly_branch where branch=day_branch)) ], null);
$$;
-- 取某日高風險症狀：select * from symptom where ten_god = any(gods_triggered('丁','乙','卯'));
